// Vérification de l'authentification Jarvis
const secret = $input.first().json.headers['x-jarvis-secret'] || '';
const expected = process.env.N8N_WEBHOOK_SECRET || '';

if (expected && secret !== expected) {
  return [{ json: { status: 'error', message: 'Unauthorized' } }];
}

// Récupère le message envoyé (ou 'ping' par défaut)
const message = $input.first().json.body?.message || 'ping';

return [
  {
    json: {
      status: 'success',
      reply: 'n8n est connecté et opérationnel',
      echo: message,
      timestamp: new Date().toISOString(),
      service: 'Jarvis Automation Engine'
    }
  }
];
